    "ks_problem": {
      "type": "ks-problem",
      "settings": {
        "image": "shopify://shop_images/ks-before.jpg",
        "alt": "Kocię gryzie dłoń z zadrapaniami",
        "eyebrow": "Znasz to?",
        "quote": "Masz na rękach więcej zadrapań, niż twój kot ma miesięcy.",
        "text": "<p>Kocię nie jest złośliwe. W miocie ćwiczyłoby polowanie na rodzeństwie: łapanie, gryzienie, kopanie tylnymi łapami. W mieszkaniu jedynym ruszającym się celem jesteś ty. Twoje dłonie, kostki, stopy pod kołdrą.</p><p>Uciekanie rękami tylko nakręca zabawę. Kot potrzebuje przeciwnika, którego wolno atakować.</p>"
      }
    },
    "ks_steps": {
      "type": "ks-steps",
      "settings": {
        "eyebrow": "Jak to działa",
        "heading": "Kot dostaje rodzeństwo do zapasów",
        "lead": "Trzy kroki, bez nauki i bez baterii."
      },
      "blocks": {
        "step_1": {
          "type": "step",
          "settings": {
            "image": "shopify://shop_images/ks-step1.jpg",
            "title": "Zakładasz na rękę",
            "text": "Wsuwasz dłoń do środka pacynki, a długi rękaw zakrywa przedramię aż do łokcia."
          }
        },
        "step_2": {
          "type": "step",
          "settings": {
            "image": "shopify://shop_images/ks-step2.jpg",
            "title": "Kot poluje",
            "text": "Poruszasz łapkami i głową pacynki. Kot widzi przeciwnika, a nie twoje palce, i atakuje z pełną siłą."
          }
        },
        "step_3": {
          "type": "step",
          "settings": {
            "image": "shopify://shop_images/ks-step3.jpg",
            "title": "Kot odpoczywa",
            "text": "Kilkanaście minut zapasów i kot ma gdzie wyładować energię. Potem zwykle przychodzi pora na drzemkę."
          }
        }
      },
      "block_order": [
        "step_1",
        "step_2",
        "step_3"
      ]
    },
    "ks_ba": {
      "type": "ks-before-after",
