        "before": "shopify://shop_images/ks-before.jpg",
        "before_label": "Przed",
        "before_text": "Kot gryzie dłonie, bo nie ma nic innego do łapania.",
        "after": "shopify://shop_images/ks-after.jpg",
        "after_label": "Po",
        "after_text": "Kot gryzie pacynkę, a przedramię jest w osłonie."
      }
    },
