      "type": "ks-for-you",
      "settings": {
        "eyebrow": "Czy to dla Ciebie",
        "heading": "Rozpoznajesz się?"
      },
      "blocks": {
        "who_1": {
          "type": "persona",
          "settings": {
            "who": "Masz pierwszego kota, kocię",
            "text": "Twój kot nie jest agresywny. Po prostu jesteś jedyną rzeczą w domu, która się rusza."
          }
        },
        "who_2": {
          "type": "persona",
          "settings": {
            "who": "Kot budzi cię w nocy",
            "text": "Jest 4:30, a kot właśnie skoczył ci na stopy, bo przez cały dzień nie miał się z kim wyszaleć."
          }
        },
        "who_3": {
          "type": "persona",
          "settings": {
            "who": "W domu jest małe dziecko",
            "text": "Twoje dziecko chowa nogi pod kocem, bo kot poluje na każdy ruch."
          }
        }
      },
