      "type": "ks-shipping",
      "settings": {
        "eyebrow": "Dostawa i zwroty",
        "heading": "Mówimy wprost, ile to trwa",
        "lead": "Paczka jedzie z magazynu naszego dostawcy w Chinach. Nie udajemy, że to 24 godziny.",
